create or replace function public.svc_layer1_resolve_source_provider_mappings(p_source_id uuid) returns table(source_entity_key text,source_entity_name text,provider_id uuid,metadata jsonb) language sql stable security definer set search_path='public','pipeline' as $$ select m.source_entity_key,m.source_entity_name,m.provider_id,m.metadata from pipeline.source_provider_mappings m where m.source_id=p_source_id and m.status='verified' order by m.source_entity_name,m.source_entity_key $$; revoke all on function public.svc_layer1_resolve_source_provider_mappings(uuid) from public,anon,authenticated; grant execute on function public.svc_layer1_resolve_source_provider_mappings(uuid) to service_role;
